function digitPower(base, digits, modulus) {
  const exponent = Number(digits.join(""));
  const factor = base % modulus;
  let result = 1 % modulus;
  for (let i = 0; i < exponent; i++) {
    result = (result * factor) % modulus;
  }
  return result;
}

function digitPower(base, digits, modulus) {
  let exponent = BigInt(digits.join(""));
  let factor = base % modulus;
  let result = 1 % modulus;
  while (exponent > 0n) {
    if (exponent % 2n === 1n) result = (result * factor) % modulus;
    factor = (factor * factor) % modulus;
    exponent = exponent / 2n;
  }
  return result;
}

function digitPower(base, digits, modulus) {
  const smallPower = (value, exponent) => {
    let result = 1 % modulus;
    let factor = value % modulus;
    while (exponent > 0) {
      if (exponent & 1) result = (result * factor) % modulus;
      factor = (factor * factor) % modulus;
      exponent >>= 1;
    }
    return result;
  };
  let result = 1 % modulus;
  for (const digit of digits) {
    result = (smallPower(result, 10) * smallPower(base, digit)) % modulus;
  }
  return result;
}
